import java.util.*;

class TwoSum {
  private final Map<Long, Integer> count = new HashMap<>();

  public TwoSum() {}

  public void add(int number) {
    count.merge((long) number, 1, Integer::sum);
  }

  public boolean find(int value) {
    for (Map.Entry<Long, Integer> e : count.entrySet()) {
      long other = value - e.getKey();
      if (other == e.getKey() ? e.getValue() > 1 : count.containsKey(other)) return true;
    }
    return false;
  }
}
